-- Owner ledger (PostgreSQL, synthetic) as a Zetaris JDBC datasource
-- Generated by scripts/onboard.ts from src/data/eurostat.ts. One statement per call (Zetaris Lightning SQL).
-- The COMPILE USL statement is multi-table and must be sent as ONE statement.

-- ledger datasource
CREATE DATASOURCE CAUSEWAY_LEDGER DESCRIBE BY "Owner ledger, PostgreSQL, synthetic" OPTIONS (jdbcdriver "org.postgresql.Driver", jdbcurl "jdbc:postgresql://causeway-ledger:5432/causeway", username "causeway", password "${CAUSEWAY_LEDGER_PASSWORD}", fetchsize "1000");

-- ledger tables
REGISTER DATASOURCE TABLES FROM CAUSEWAY_LEDGER;
